    const h = Math.max(10, height - m.top - m.bottom);
    const x = d3.scaleLinear().domain([hs[0].min, hs[0].max]).range([0, w]);
    const y = d3.scaleLinear().domain([0, d3.max(ys.flat()) || 1]).nice().range([h, 0]);
